// Reports the ten most frequent words in a text file.
// A word is a maximal run of ASCII letters and digits; everything else separates words.

export function countWords(bytes: Uint8Array): Map<string, number> {
  const counts = new Map<string, number>();
  let start = -1;
  let word = "";
  for (let i = 0; i <= bytes.length; i++) {
    const b = i < bytes.length ? bytes[i] : 0;
    const isDigit = b >= 0x30 && b <= 0x39;
    const isUpper = b >= 0x41 && b <= 0x5a;
    const isLower = b >= 0x61 && b <= 0x7a;
    if (isDigit || isUpper || isLower) {
      if (start < 0) start = i;
    } else if (start >= 0) {
      word = asciiLower(bytes, start, i);
      counts.set(word, (counts.get(word) ?? 0) + 1);
      start = -1;
    }
  }
  return counts;
}

function asciiLower(bytes: Uint8Array, start: number, end: number): string {
  let s = "";
  const CHUNK = 8192;
  for (let i = start; i < end; i += CHUNK) {
    const stop = Math.min(end, i + CHUNK);
    const codes = new Array<number>(stop - i);
    for (let j = i; j < stop; j++) {
      const b = bytes[j];
      codes[j - i] = b >= 0x41 && b <= 0x5a ? b + 0x20 : b;
    }
    s += String.fromCharCode(...codes);
  }
  return s;
}

export function topWords(
  counts: Map<string, number>,
  n = 10,
): [string, number][] {
  // Words are pure ASCII, so UTF-16 code unit comparison equals byte comparison.
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    .slice(0, n);
}

export function report(bytes: Uint8Array): string {
  return topWords(countWords(bytes))
    .map(([w, c]) => `${w} ${c}\n`)
    .join("");
}

if (import.meta.main) {
  const path = Deno.args[0];
  const bytes = await Deno.readFile(path);
  const out = report(bytes);
  if (out.length > 0) {
    const data = new TextEncoder().encode(out);
    let written = 0;
    while (written < data.length) {
      written += await Deno.stdout.write(data.subarray(written));
    }
  }
}
EOF
cat > main_test.ts <<'EOF'
import { report } from "./main.ts";

function assertEquals(actual: unknown, expected: unknown) {
  if (actual !== expected) {
    throw new Error(`expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const enc = (s: string) => new TextEncoder().encode(s);

Deno.test("empty input writes nothing", () => {
  assertEquals(report(enc("")), "");
  assertEquals(report(enc("  ,.!? \n\t-- é ü")), "");
});

Deno.test("case-insensitive counting, lower-case output", () => {
  assertEquals(report(enc("The the THE tHe")), "the 4\n");
});

Deno.test("non-ASCII bytes separate words", () => {
  assertEquals(report(enc("caféx naïve")), "caf 1\nna 1\nve 1\nx 1\n");
});

Deno.test("digits are word characters; underscore and apostrophe separate", () => {
  assertEquals(report(enc("abc123 don't a_b 123")), "123 1\na 1\nabc123 1\nb 1\ndon 1\nt 1\n");
});

Deno.test("ties broken by bytes ascending (digits < letters)", () => {
  assertEquals(report(enc("b a 9 b a 9 z")), "9 2\na 2\nb 2\nz 1\n");
});

Deno.test("only top ten reported", () => {
  const words = "a b c d e f g h i j k l".split(" ");
  const text = words.map((w, i) => (w + " ").repeat(20 - i)).join("");
  const lines = report(enc(text)).trimEnd().split("\n");
  assertEquals(lines.length, 10);
  assertEquals(lines[0], "a 20");
  assertEquals(lines[9], "j 11");
});

Deno.test("invalid UTF-8 handled as separators", () => {
  assertEquals(report(new Uint8Array([0x61, 0xff, 0x62, 0x80, 0x61])), "a 2\nb 1\n");
});

Deno.test("very long word", () => {
  const w = "X".repeat(300000);
  assertEquals(report(enc(w)), "x".repeat(300000) + " 1\n");
});
EOF
deno check main.ts main_test.ts && deno test && printf 'Hello, hello world! World? WORLD.\n' > /tmp/wf.txt && deno run --allow-read main.ts /tmp/wf.txt; echo "exit $?"

